{
  "technical_and_design_decisions": [
    "Target the existing Spring XD 1.x codebase (stream/module/message-bus architecture with ZooKeeper coordination); no platform migration is part of this increment.",
    "U2: Expose the Kafka starting offset as a stream deployment property (e.g., startOffset=earliest|latest|<explicit offset>), evaluated only at (re)deployment time.",
    "U2: Persist consumer progress via committed offsets (Kafka/ZooKeeper-backed offset storage with periodic/asynchronous commits) so module progress survives crashes of a running stream.",
    "U2: Resolve the open TBD as follows: on undeploy/redeploy without an explicit offset, resume from the last committed offset; redeploying with an explicit offset re-reads from that offset.",
    "U3: Implement static (manual) partition assignment for Kafka source modules: at deployment time the XD admin computes the partition-to-module-instance mapping, stores it in ZooKeeper, and passes explicit partition lists to each consumer, avoiding consumer-group rebalancing.",
    "U4: Extend the message bus binding layer so bus partitions are statically pre-allocated to container nodes at deployment time; the partition-to-node mapping is kept in ZooKeeper and re-applied after container crash/redeploy so no rebalancing occurs.",
    "U5: Treat Spark as a time-boxed research spike: build a Spark Streaming POC integrated with XD via a module/bus bridge and deliver an evaluation report plus a recommended design; production Spark integration is out of scope.",
    "U6: Implement the reactor-stream processor module using Project Reactor: tumbling time windows (timeWindow option), SpEL-based field extraction (field option), and aggregation expressions (min, avg, etc.), emitting results downstream at window close.",
    "U7: Implement microbatching as a batch-interval buffering option on the ingestion path (e.g., http --batchInterval=10s); buffer messages and flush them as a batch on interval expiry or size threshold.",
    "U8: Build the performance environment on Rackspace cloud with scripted provisioning, a Kafka cluster, an XD cluster, and a benchmark harness (custom drivers/JMeter); run Kafka baselines first, then XD use-case benchmarks, and document results.",
    "Testing approach: unit tests plus integration tests using embedded/in-process Kafka and the existing XD test framework; manual verification for Rackspace benchmarks.",
    "Documentation delivered in the project wiki (GitHub wiki) covering all new modules, options, and features."
  ],
  "assumptions": [
    "A single developer performs all work; estimates are effort in workdays (8 hours each), not elapsed calendar time.",
    "The existing Spring XD codebase, Gradle build, and CI are available and functional, and the developer is familiar with the codebase.",
    "A development/test Kafka cluster and ZooKeeper ensemble are available; the existing Kafka source uses Kafka 0.8.x-era client APIs.",
    "New configuration is exposed via XD shell/DSL deployment properties only; no admin UI changes are required.",
    "A Rackspace cloud account with sufficient quota and credentials is available, using standard Ubuntu images.",
    "The Spark deliverable is prototype/POC quality plus a design recommendation; production-grade Spark integration is excluded from this increment.",
    "Estimates include design, implementation, unit/integration testing, debugging, and wiki documentation, all performed by the same developer; no separate QA or documentation teams.",
    "U2's open TBD is resolved per the stated design decision (resume from last committed offset unless an explicit starting offset is provided).",
    "Third-party libraries (Reactor, Spark, Kafka clients) are used as-is; no upstream contributions or library fixes are required.",
    "Estimates exclude non-project overhead (vacations, company meetings) but include normal development-flow activities such as code review self-checks and build maintenance for the touched components."
  ],
  "activities": [
    {
      "activity_id": "A01",
      "activity_name": "Requirements analysis and high-level design",
      "activity_description": "Analyze user stories U1-U8, produce high-level and component-level technical designs for Kafka offset handling (U2), Kafka source partition pre-allocation (U3), message-bus partition pre-allocation (U4), reactor-stream module (U6), and microbatching (U7), including deployment-property schema and ZooKeeper state layout.",
      "most_likely_effort": 5
    },
    {
      "activity_id": "A02",
      "activity_name": "U2 - Starting-offset option for Kafka source",
      "activity_description": "Implement the starting-offset deployment property in the Kafka source module: parse/validate the option, resolve earliest/latest/explicit offsets, and apply the offset only when the stream is (re)deployed.",
      "most_likely_effort": 6
    },
    {
      "activity_id": "A03",
      "activity_name": "U2 - Offset persistence and crash recovery",
      "activity_description": "Implement offset commit strategy (Kafka/ZooKeeper-backed) so in-flight progress survives module crashes, and implement undeploy/redeploy resume semantics (resume from committed offset unless explicit offset given).",
      "most_likely_effort": 5
    },
    {
      "activity_id": "A04",
      "activity_name": "U2 - Tests for offset handling",
      "activity_description": "Write unit and integration tests (embedded Kafka) covering initial offset resolution, crash recovery, and undeploy/redeploy replay behavior.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A05",
      "activity_name": "U3 - Static partition pre-allocation for Kafka source modules",
      "activity_description": "Implement deployment-time computation of partition-to-module-instance assignment, store the mapping in ZooKeeper, pass explicit partition lists to each Kafka source instance, and switch consumers to manual partition assignment to eliminate rebalancing.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A06",
      "activity_name": "U3 - Tests and validation of source partition pre-allocation",
      "activity_description": "Test multi-instance stream deployments: verify correct static assignment, no consumer-group rebalancing, and stable behavior across redeployments.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A07",
      "activity_name": "U4 - Message-bus partition pre-allocation across nodes",
      "activity_description": "Extend the message bus binding layer to statically pre-allocate bus partitions to container nodes at stream deployment; maintain the partition-to-node mapping in ZooKeeper and re-apply it after container crash or redeploy so rebalancing does not occur.",
      "most_likely_effort": 10
    },
    {
      "activity_id": "A08",
      "activity_name": "U4 - Tests and validation of bus partition pre-allocation",
      "activity_description": "Integration tests for container crash and redeploy scenarios verifying stable partition assignment and continued message delivery without rebalancing.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "A09",
      "activity_name": "U5 - Spark investigation, POC, and design recommendation",
      "activity_description": "Time-boxed research spike: set up Spark/Spark Streaming, build a POC integrating Spark with XD (module/bus bridge), evaluate integration options, and deliver a written evaluation report with the recommended design and implementation approach.",
      "most_likely_effort": 10
    },
    {
      "activity_id": "A10",
      "activity_name": "U6 - reactor-stream processor module implementation",
      "activity_description": "Implement the reactor-stream processor using Project Reactor: tumbling time windows (timeWindow), SpEL-based field extraction (field), and aggregation expressions (min, avg, etc.), emitting aggregated results downstream at window close.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A11",
      "activity_name": "U6 - Module packaging, samples, and tests",
      "activity_description": "Package and register the reactor-stream processor module (metadata/options), create usage samples matching the spec examples, and write unit and integration tests.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A12",
      "activity_name": "U7 - Microbatching capability implementation",
      "activity_description": "Implement batch-interval buffering on the ingestion path (e.g., http --batchInterval=10s): buffer incoming messages and flush them as a batch on interval expiry or size threshold, integrating with the source/bus pipeline.",
      "most_likely_effort": 6
    },
    {
      "activity_id": "A13",
      "activity_name": "U7 - Microbatching tests and throughput validation",
      "activity_description": "Unit/integration tests for batching correctness (interval flush, threshold flush, edge cases) and a basic throughput check demonstrating performance improvement.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A14",
      "activity_name": "U8 - Rackspace performance infrastructure and benchmark harness",
      "activity_description": "Provision Rackspace VMs via scripts, install and configure a Kafka cluster and an XD cluster, and build the benchmark harness (load drivers, metrics collection, run scripts).",
      "most_likely_effort": 5
    },
    {
      "activity_id": "A15",
      "activity_name": "U8 - Kafka baselines and XD use-case benchmarks",
      "activity_description": "Execute Kafka baseline benchmarks (producer/consumer throughput and latency), then run XD stream use-case benchmarks, collect results, and document findings.",
      "most_likely_effort": 5
    },
    {
      "activity_id": "A16",
      "activity_name": "U1 - Wiki documentation",
      "activity_description": "Write wiki documentation covering the new Kafka source options (starting offset, partition pre-allocation), message-bus partition pre-allocation, the reactor-stream processor module, microbatching, and the performance benchmarking setup/results.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "A17",
      "activity_name": "Cross-feature integration testing and release preparation",
      "activity_description": "End-to-end integration testing of all increment features together, defect fixing, final regression runs, and release packaging/preparation.",
      "most_likely_effort": 5
    }
  ],
  "reported_total": {
    "most_likely_effort": 92
  }
}

